import numpy as np
mask_c = df['등급 (A/B/C)'] == 'C'
sub = df[mask_c].copy()
def get_reason(row):
    high_metal = row['잔류금속 (wt%)'] > 5.0
    low_ig_id = row['IG/ID'] < 2.2
    if high_metal and low_ig_id:
        return '둘 다'
    elif high_metal:
        return '잔류금속 > 5.0 wt%만'
    elif low_ig_id:
        return 'IG/ID < 2.2만'
    else:
        return '기타'
sub['사유'] = sub.apply(get_reason, axis=1)
df = sub[sub['사유'] != '기타']
